<?php
declare(strict_types=1);namespace App\Application\Chat;
final class ChatFileUploader{
private const TYPES=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf','application/msword'=>'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document'=>'docx','application/vnd.ms-excel'=>'xls','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'=>'xlsx'];
public static function uploadMany(array $files,string $root):array{$normalized=[];if(isset($files['name'])&&is_array($files['name'])){foreach($files['name'] as$i=>$name)$normalized[]=['name'=>$name,'type'=>$files['type'][$i]??'','tmp_name'=>$files['tmp_name'][$i]??'','error'=>$files['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$files['size'][$i]??0];}elseif(isset($files['name']))$normalized[]=$files;if(count($normalized)>10)throw new \RuntimeException('Maximum 10 fichiers par envoi.');$uploads=[];foreach($normalized as$file){if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;if(($file['error']??0)!==UPLOAD_ERR_OK||(int)$file['size']>10*1024*1024)throw new \RuntimeException('Un fichier est invalide ou dépasse 10 Mo.');$mime=(string)(new \finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);if(!isset(self::TYPES[$mime]))throw new \RuntimeException('Un format de fichier n’est pas accepté.');$dir=$root.'/photo/chat';if(!is_dir($dir)&&!mkdir($dir,0777,true)&&!is_dir($dir))throw new \RuntimeException('Stockage indisponible.');@chmod($dir,0777);$name='chat_'.bin2hex(random_bytes(12)).'.'.self::TYPES[$mime];if(!move_uploaded_file((string)$file['tmp_name'],$dir.'/'.$name))throw new \RuntimeException('Envoi impossible.');$uploads[]=['path'=>'photo/chat/'.$name,'original'=>basename((string)$file['name']),'mime'=>$mime];}return $uploads;}
}
